func openTestBroker(t *testing.T, ctx context.Context, cfg Config) (*Runtime, error) {
	t.Helper()
	runtime, err := Start(ctx, cfg)
	if err != nil {
		return nil, err
	}
	t.Cleanup(func() { _ = runtime.Close() })
	raw, err := os.ReadFile(cfg.Embedded.CellJWTFile)
	if err != nil {
		t.Fatal(err)
	}
	if err := runtime.ApplyCellClaim(ctx, 1, string(raw)); err != nil {
		t.Fatal(err)
	}
	if err := runtime.Bridge().OpenUntil(1, string(raw), time.Now().Add(5*time.Minute)); err != nil {
		t.Fatal(err)
	}
	return runtime, nil
}

func (keys testRegionKeys) childKey(t *testing.T, child string) nkeys.KeyPair {
	t.Helper()
	if key, ok := keys.children[child]; ok {
		return key
	}
	key, err := nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	keys.children[child] = key
	return key
}

func newTestRegionKeys(t *testing.T) testRegionKeys {
	t.Helper()
	var keys testRegionKeys
	var err error
	if keys.operator, err = nkeys.CreateOperator(); err != nil {
		t.Fatal(err)
	}
	for _, account := range []*nkeys.KeyPair{&keys.system, &keys.cell, &keys.interregion} {
		if *account, err = nkeys.CreateAccount(); err != nil {
			t.Fatal(err)
		}
	}
	keys.operatorID, _ = keys.operator.PublicKey()
	keys.systemID, _ = keys.system.PublicKey()
	keys.cellID, _ = keys.cell.PublicKey()
	keys.interregionID, _ = keys.interregion.PublicKey()
	keys.children = map[string]nkeys.KeyPair{}
	keys.t = t
	return keys
}

func (keys testRegionKeys) claims(contract InterRegionContract, links int) (*jwt.AccountClaims, *jwt.AccountClaims, *jwt.AccountClaims) {
	childKeys := map[string]string{}
	for child := range contract.Subtrees {
		childKeys[child], _ = keys.childKey(keys.t, child).PublicKey()
	}
	system := jwt.NewAccountClaims(keys.systemID)
	system.Limits.LeafNodeConn = 0
	cell := jwt.NewAccountClaims(keys.cellID)
	cell.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: 64 << 20, DiskStorage: 256 << 20, Streams: 20, Consumer: 20}
	contract.ApplyCell(cell, keys.interregionID)
	interregion := jwt.NewAccountClaims(keys.interregionID)
	contract.ApplyInterRegion(interregion, keys.cellID, links, childKeys)
	return system, cell, interregion
}

func newTestRegion(t *testing.T, root, cell string, topology LeafTopology) *testRegion {
	t.Helper()
	if err := os.MkdirAll(root, 0o700); err != nil {
		t.Fatal(err)
	}
	keys := newTestRegionKeys(t)
	peers := topology.Peers(cell)
	subtrees := topology.Subtrees(cell)
	contract := InterRegionContract{Cell: cell, Peers: peers, GlobalHome: topology.Hub, Subtrees: subtrees}
	links := topology.Links(cell)
	system, cellClaim, interregion := keys.claims(contract, links)
	operator := jwt.NewOperatorClaims(keys.operatorID)
	operator.SystemAccount = keys.systemID
	write := func(name, data string) string {
		t.Helper()
		path := filepath.Join(root, name)
		if err := os.WriteFile(path, []byte(data), 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}
	encode := func(name string, claim interface {
		Encode(nkeys.KeyPair) (string, error)
	},
	) string {
		t.Helper()
		raw, err := claim.Encode(keys.operator)
		if err != nil {
			t.Fatal(err)
		}
		return write(name, raw)
	}
	systemUser, _ := nkeys.CreateUser()
	systemUserID, _ := systemUser.PublicKey()
	tlsFiles := testBridgeTLS(t, filepath.Join(root, "tls"))
	cfg := Config{
		Cell: cell, Instance: "broker-a", Replicas: 1, TLS: tlsFiles,
		CredentialsFile: testJWTUserCredentials(t, root, "controller.creds", keys.cell, keys.cellID, nil, nil),
		Embedded: &Embedded{
			Host: "127.0.0.1", Port: freeClientPort(t), StoreDir: filepath.Join(root, "store"),
			TLS: tlsFiles, RouteTLS: tlsFiles,
			OperatorJWTFile: encode("operator.jwt", operator),
			SystemJWTFile:   encode("system.jwt", system),
			CellJWTFile:     encode("cell.jwt", cellClaim),
			SystemCredentialsFile: testJWTUserCredentialsWithKey(t, root, "system.creds", keys.system, keys.systemID, systemUser,
				[]string{"$SYS.REQ.ACCOUNT." + keys.cellID + ".CLAIMS.UPDATE"}, []string{inboxPrefix(cell, systemUserID) + ".>"}),
			TicketPublicKeyFile: write("ticket.pub", "unused"),
			BrokerIDs:           []string{"broker-a"},
			InterRegion: &InterRegion{
				Peers: peers, AccountJWTFile: encode("interregion.jwt", interregion),
				GlobalHome: topology.Hub, Subtrees: subtrees,
			},
		},
	}
	return &testRegion{testRegionKeys: keys, cfg: cfg}
}

func (r *Runtime) ApplyCellClaim(ctx context.Context, sequence uint64, raw string) error {
	if r == nil || r.server == nil || r.resolver == nil || r.systemConn == nil ||
		sequence == 0 || raw == "" {
		return errors.New("production cell claim application is unavailable")
	}
	r.claimMu.Lock()
	defer r.claimMu.Unlock()
	if sequence < r.appliedSequence {
		return errors.New("cell claim sequence is stale")
	}
	if r.bridge != nil {
		r.bridge.FenceClaim(sequence)
	}
	if claim, err := jwt.DecodeAccountClaims(raw); err != nil || !r.SignedByPinnedOperator(claim) {
		return errors.New("cell claim is not signed by the pinned operator")
	}
	// Store runs the contract and issued-at checks; only then is the claim
	// installed, locally and directly. The server ignores CLAIMS.UPDATE
	// requests (see accountResolver.IsTrackingUpdate), so no routed or
	// client-sent claim can skip these checks.
	if err := r.resolver.Store(r.resolver.cell, raw); err != nil {
		return err
	}
	account, err := r.server.LookupAccount(r.resolver.cell)
	if err != nil {
		return err
	}
	current, err := r.server.Accountz(&server.AccountzOptions{Account: r.resolver.cell})
	if err != nil {
		return err
	}
	if current.Account == nil {
		return errors.New("cell account is not loaded")
	}
	if current.Account.Jwt != raw {
		if err := r.server.UpdateAccountClaimJWT(account, raw); err != nil {
			return fmt.Errorf("install cell account claim: %w", err)
		}
		current, err = r.server.Accountz(&server.AccountzOptions{Account: r.resolver.cell})
		if err != nil || current.Account == nil || current.Account.Jwt != raw {
			return errors.New("cell JWT update lacks local exact readback")
		}
	}
	r.appliedSequence = sequence
	return nil
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func serverOptionsForStart(cfg Config, identityRekey bool) (*server.Options, error) {
	e := cfg.Embedded
	if err := os.MkdirAll(e.StoreDir, 0o700); err != nil {
		return nil, fmt.Errorf("create regional JetStream store: %w", err)
	}
	name := ServerName(cfg.Cell, cfg.Instance)
	if err := pinStoreIdentity(e.StoreDir, name, cfg.Cell+"-"+cfg.Instance); err != nil {
		return nil, err
	}
	options := &server.Options{
		ServerName:        name,
		Host:              e.Host,
		Port:              e.Port,
		JetStream:         true,
		JetStreamMaxStore: e.StoreLimitBytes(),
		StoreDir:          e.StoreDir,
		// JetStream clustering uses the system account to coordinate metadata.
		SystemAccount: "$SYS",
		Accounts:      []*server.Account{server.NewAccount("$SYS")},
		Cluster: server.ClusterOpts{
			Name: cfg.Cell,
			Host: e.RouteHost,
			Port: e.RoutePort,
		},
		LameDuckDuration:    lameDuckDuration,
		LameDuckGracePeriod: lameDuckGracePeriod,
		// NATS logs every failed reconnect to a lost route, gateway or leaf
		// at ERR by default: about one a second per pooled route while a peer
		// reboots. Report the first and then one a minute (TS-661).
		ReconnectErrorReports: reconnectErrorReports,
	}
	operator, systemJWT, cellJWT, systemID, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return nil, err
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, systemID); err != nil {
		return nil, err
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return nil, errors.New("controller credentials do not belong to the regional cell account")
	}
	resolver := newAccountResolver(systemID, systemJWT, cellID, cellJWT)
	options.TrustedOperators = []*jwt.OperatorClaims{operator}
	options.SystemAccount = systemID
	options.Accounts = nil
	options.AccountResolver = resolver
	options.JetStreamDomain = cfg.Cell
	options.DontListen = true
	options.Cluster.NoAdvertise = true
	if e.InterRegion != nil {
		if err := interRegionServerOptions(cfg, options, resolver, operator); err != nil {
			return nil, err
		}
	}
	if e.Link != nil {
		if err := linkServerOptions(cfg, options, resolver); err != nil {
			return nil, err
		}
	}
	if identityRekey && (e.InterRegion != nil || e.Link != nil) {
		options.LeafNode = server.LeafNodeOpts{}
	}
	if cfg.Replicas > 1 {
		for _, raw := range e.Routes {
			route, err := url.Parse(raw)
			if err != nil || route.Host == "" || route.User != nil || route.Scheme != "nats-route" {
				return nil, fmt.Errorf("invalid NATS route %q", raw)
			}
			options.Routes = append(options.Routes, route)
		}
	}
	if cfg.Replicas > 1 && e.RouteTLS.complete() {
		// Routes reload a renewed leaf or CA bundle on their next handshake.
		routeTLS, err := NewReloadingTLS(e.RouteTLS, "route")
		if err != nil {
			return nil, err
		}
		options.Cluster.TLSConfig = routeTLS.PeerConfig()
	}
	seenKeys := make(map[string]struct{}, len(e.Users))
	for _, user := range e.Users {
		if !nkeys.IsValidPublicUserKey(user.PublicKey) {
			return nil, errors.New("invalid user NKey in embedded NATS users")
		}
		if _, exists := seenKeys[user.PublicKey]; exists {
			return nil, errors.New("duplicate embedded NATS user key")
		}
		seenKeys[user.PublicKey] = struct{}{}
		permissions, err := userPermissions(cfg.Cell, user)
		if err != nil {
			return nil, err
		}
		options.Nkeys = append(options.Nkeys, &server.NkeyUser{Nkey: user.PublicKey, Permissions: permissions})
	}
	if e.RoutePasswordFile != "" {
		secret, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return nil, fmt.Errorf("read NATS route secret: %w", err)
		}
		defer clear(secret)
		password := strings.TrimSpace(string(secret))
		if len(password) < 16 {
			return nil, errors.New("NATS route secret must be at least 16 bytes")
		}
		options.Cluster.Username = e.RouteUser
		options.Cluster.Password = password
		for _, route := range options.Routes {
			route.User = url.UserPassword(e.RouteUser, password)
		}
	}
	return options, nil
}

func (r *Runtime) ObserveCluster() (ClusterObservation, error) {
	if r == nil || r.server == nil {
		return ClusterObservation{}, errors.New("cluster observation requires an embedded regional NATS server")
	}
	observation := ClusterObservation{ServerName: r.serverName, Running: r.server.Running(),
		ExpectedPeers: slices.Clone(r.brokerNames)}
	if !observation.Running {
		return observation, nil
	}
	if routes, err := r.server.Routez(nil); err == nil {
		for _, route := range routes.Routes {
			if route != nil && route.RemoteName != "" && !slices.Contains(observation.Routes, route.RemoteName) {
				observation.Routes = append(observation.Routes, route.RemoteName)
			}
		}
		slices.Sort(observation.Routes)
	}
	info, err := r.server.Jsz(nil)
	if err != nil {
		return observation, err
	}
	if info.Disabled {
		// JetStream was never enabled or was shut down after a store
		// failure, which also clears JetStreamIsClustered while the NATS
		// server keeps running. Never present that as a healthy group.
		return observation, ErrJetStreamDisabled
	}
	if info.Meta == nil {
		if !r.server.JetStreamIsClustered() && len(r.brokerNames) <= 1 {
			// A standalone broker is its own single-member metadata group.
			observation.MetaLeader, observation.MetaSize, observation.MetaQuorum = r.serverName, 1, 1
		}
		return observation, nil
	}
	observation.MetaLeader = info.Meta.Leader
	observation.MetaSize = info.Meta.Size
	observation.MetaQuorum = info.Meta.QuorumNeeded
	observation.MetaPeers = metaReplicas(info.Meta.Replicas)
	return observation, nil
}

func (r *Runtime) StreamHealth(ctx context.Context) ([]StreamState, error) {
	if r == nil || r.server == nil || !r.server.Running() || r.js == nil {
		return nil, errors.New("embedded regional NATS server is not running")
	}
	if info, err := r.server.Jsz(nil); err != nil {
		return nil, err
	} else if info.Disabled {
		return nil, ErrJetStreamDisabled
	}
	lister := r.js.StreamNames(ctx)
	var names []string
	for name := range lister.Name() {
		names = append(names, name)
	}
	if err := lister.Err(); err != nil {
		return nil, fmt.Errorf("list streams: %w", err)
	}
	slices.Sort(names)
	var states []StreamState
	lagging := 0
	for _, name := range names {
		requestCtx, cancel := context.WithTimeout(ctx, streamInfoTimeout)
		stream, err := r.js.Stream(requestCtx, name)
		cancel()
		if errors.Is(err, jetstream.ErrStreamNotFound) {
			continue
		}
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		state := StreamState{Name: name, Lagging: true}
		if err == nil {
			info := stream.CachedInfo()
			state.Lagging = StreamLagging(info)
			state.Peers = streamPeers(info, r.server.Name())
		}
		states = append(states, state)
		if state.Lagging {
			if lagging++; lagging == maxLaggingStreams {
				break
			}
		}
	}
	return states, nil
}

func streamPeers(info *jetstream.StreamInfo, self string) []string {
	if info == nil || info.Cluster == nil {
		return []string{self}
	}
	var peers []string
	if info.Cluster.Leader != "" {
		peers = append(peers, info.Cluster.Leader)
	}
	for _, peer := range info.Cluster.Replicas {
		if peer != nil && peer.Name != "" && !slices.Contains(peers, peer.Name) {
			peers = append(peers, peer.Name)
		}
	}
	slices.Sort(peers)
	return peers
}

func StreamLagging(info *jetstream.StreamInfo) bool {
	if info == nil {
		return true
	}
	cluster := info.Cluster
	if cluster == nil {
		return false
	}
	if cluster.Leader == "" {
		return true
	}
	for _, peer := range cluster.Replicas {
		if peer == nil || peer.Offline || !peer.Current {
			return true
		}
	}
	return false
}

func (r *Runtime) Observe(ctx context.Context) (observability.NATSView, error) {
	if r == nil || r.server == nil || !r.server.Running() {
		return observability.NATSView{}, errors.New("embedded NATS server is not running")
	}
	if err := ctx.Err(); err != nil {
		return observability.NATSView{}, err
	}
	varz, err := r.server.Varz(nil)
	if err != nil {
		return observability.NATSView{}, err
	}
	// shortcut: Routez has no read limit, use pagination if the embedded API adds it.
	routes, err := r.server.Routez(nil)
	if err != nil {
		return observability.NATSView{}, err
	}
	view := observability.NATSView{
		ServerName: varz.Name, RaftNodeID: r.server.NodeName(), Connections: varz.Connections, Routes: varz.Routes,
		SlowConsumers: varz.SlowConsumers,
		InMsgs:        varz.InMsgs, OutMsgs: varz.OutMsgs, InBytes: varz.InBytes, OutBytes: varz.OutBytes,
	}
	observeRoutes(&view, routes)
	if varz.JetStream.Config != nil {
		view.StoreLimitBytes = varz.JetStream.Config.MaxStore
	}
	jsz, err := r.server.Jsz(&server.JSzOptions{Accounts: true, Streams: true, Consumer: true, Config: true})
	if err != nil {
		return observability.NATSView{}, err
	}
	if jsz.Disabled {
		return observability.NATSView{}, ErrJetStreamDisabled
	}
	view.StoreUsedBytes = jsz.Store
	if jsz.Config.MaxStore > 0 {
		view.StoreLimitBytes = jsz.Config.MaxStore
	}
	if meta := jsz.Meta; meta != nil {
		view.MetaLeader, view.MetaClusterSize = meta.Leader, meta.Size
		view.IsMetaLeader = meta.Leader != "" && meta.Leader == view.ServerName
		for _, peer := range meta.Replicas {
			if peer != nil {
				view.MetaPeers = append(view.MetaPeers, observability.PeerView{Name: peer.Name,
					Current: peer.Current, Offline: peer.Offline, Lag: peer.Lag, Active: peer.Active})
			}
		}
	} else if r.conn != nil {
		// A single-replica cell has no metadata group; it leads itself.
		view.IsMetaLeader, view.MetaLeader, view.MetaClusterSize = true, view.ServerName, 1
	}
	for _, account := range jsz.AccountDetails {
		if account == nil {
			continue
		}
		for _, stream := range account.Streams {
			if len(view.Streams) >= maxObservedStreams {
				view.Truncated = true
				break
			}
			view.Streams = append(view.Streams, streamView(stream))
			for _, consumer := range stream.Consumer {
				if consumer == nil {
					continue
				}
				if len(view.Consumers) >= maxObservedConsumers {
					view.Truncated = true
					break
				}
				view.Consumers = append(view.Consumers, observability.ConsumerView{
					Stream: consumer.Stream, Name: consumer.Name, NumPending: consumer.NumPending,
					NumAckPending: consumer.NumAckPending, NumRedelivered: consumer.NumRedelivered,
					NumWaiting: consumer.NumWaiting})
			}
		}
	}
	slices.SortFunc(view.Streams, func(a, b observability.StreamView) int { return cmp.Compare(a.Name, b.Name) })
	slices.SortFunc(view.Consumers, func(a, b observability.ConsumerView) int {
		if order := cmp.Compare(a.Stream, b.Stream); order != 0 {
			return order
		}
		return cmp.Compare(a.Name, b.Name)
	})
	return view, nil
}

func (b *Bridge) OpenUntil(sequence uint64, rawJWT string, deadline time.Time) error {
	if b == nil || sequence == 0 || rawJWT == "" || !time.Now().Before(deadline) {
		return errors.New("broker bridge ticket is invalid or expired")
	}
	if _, err := b.server.LookupAccount(b.account); err != nil {
		return fmt.Errorf("load broker account: %w", err)
	}
	accountz, err := b.server.Accountz(&server.AccountzOptions{Account: b.account})
	if err != nil || accountz.Account == nil || accountz.Account.Jwt != rawJWT {
		return errors.New("broker account JWT was not applied locally")
	}
	b.mu.Lock()
	if b.closed || sequence < b.floor {
		b.mu.Unlock()
		return errors.New("broker bridge is closed or claim sequence is stale")
	}
	var pairs map[*bridgePair]struct{}
	if b.open && (b.sequence != sequence || b.jwt != rawJWT) {
		pairs = b.fenceLocked()
	}
	b.sequence, b.jwt, b.deadline, b.open = sequence, rawJWT, deadline, true
	if b.timer != nil {
		b.timer.Stop()
	}
	b.timer = time.AfterFunc(time.Until(deadline), func() {
		b.mu.Lock()
		var expired map[*bridgePair]struct{}
		if b.open && b.sequence == sequence && b.deadline.Equal(deadline) {
			expired = b.fenceLocked()
		}
		b.mu.Unlock()
		closeBridgeExternal(expired)
	})
	b.mu.Unlock()
	closeBridgeExternal(pairs)
	return nil
}

