func ObserveInstalledIdentity(cfg Config) (InstallationIdentity, error) {
	if cfg.Embedded == nil {
		return InstallationIdentity{}, errors.New("installed broker identity requires production configuration")
	}
	if err := cfg.validate(); err != nil {
		return InstallationIdentity{}, err
	}
	dir, err := openInstallationDirectory(cfg.Embedded.StoreDir, false)
	if err != nil {
		return InstallationIdentity{}, err
	}
	defer unix.Close(dir)
	return observeInstalledIdentity(cfg, dir)
}

func observeInstalledIdentity(cfg Config, dir int) (InstallationIdentity, error) {
	nodeWire, err := readInstallationFileAt(dir, nodeIdentityFile, 4096)
	if err != nil {
		return InstallationIdentity{}, err
	}
	return observeInstallationIdentity(cfg, dir, nodeWire)
}

func observeInstallationIdentity(cfg Config, dir int, nodeWire []byte) (InstallationIdentity, error) {
	e := cfg.Embedded
	result := InstallationIdentity{Directory: e.StoreDir, ServerName: ServerName(cfg.Cell, cfg.Instance)}
	serverWire, err := readInstallationFileAt(dir, storeIdentityFile, 4096)
	if err != nil {
		return result, err
	}
	if string(serverWire) != result.ServerName+"\n" {
		return result, ErrStoreIdentity
	}
	var node nodeIdentity
	if err := protocol.DecodeStrict(nodeWire, &node, 4096); err != nil || node.Version != 1 || node.Cell != cfg.Cell || node.Instance != cfg.Instance {
		return result, ErrStoreIdentity
	}
	prepared, err := server.NewServer(&server.Options{ServerName: result.ServerName, DontListen: true, NoLog: true, NoSigs: true})
	if err != nil {
		return result, err
	}
	defer prepared.Shutdown()
	if node.NodeID != prepared.NodeName() {
		return result, ErrStoreIdentity
	}
	result.RaftNodeID = node.NodeID
	result.ServerNameSHA256, result.NodeIdentitySHA256 = installationDigest(serverWire), installationDigest(nodeWire)
	operatorWire, err := readInstallationFile(e.OperatorJWTFile, 64<<10)
	if err != nil {
		return result, err
	}
	operator, err := jwt.DecodeOperatorClaims(strings.TrimSpace(string(operatorWire)))
	if err != nil {
		return result, fmt.Errorf("decode installed operator: %w", err)
	}
	systemWire, err := readInstallationFile(e.SystemJWTFile, 64<<10)
	if err != nil {
		return result, err
	}
	system, err := jwt.DecodeAccountClaims(strings.TrimSpace(string(systemWire)))
	if err != nil || system.Subject != operator.SystemAccount || !operator.DidSign(system) {
		return result, errors.New("installed system account is not bound to operator")
	}
	cellWire, err := readInstallationFile(e.CellJWTFile, 64<<10)
	if err != nil {
		return result, err
	}
	cell, err := jwt.DecodeAccountClaims(strings.TrimSpace(string(cellWire)))
	if err != nil || cell.Subject == system.Subject || !operator.DidSign(cell) {
		return result, errors.New("installed cell account is not bound to operator")
	}
	result.Operator, result.SystemAccount, result.CellAccount = operator.Subject, system.Subject, cell.Subject
	for key, scope := range cell.SigningKeys {
		if scope == nil {
			if result.AccountSigner != "" {
				return result, errors.New("installed cell has multiple account signers")
			}
			result.AccountSigner = key
			continue
		}
		user, ok := scope.(*jwt.UserScope)
		if !ok || user.Key != key {
			return result, errors.New("installed broker signing scope is invalid")
		}
		switch user.Role {
		case "host":
			if result.HostSigner != "" {
				return result, errors.New("installed cell has multiple host signers")
			}
			result.HostSigner = key
		case "role":
			if result.RoleSigner != "" {
				return result, errors.New("installed cell has multiple role signers")
			}
			result.RoleSigner = key
		case linkRole:
			// The global link signer (TS-803) is no broker identity: nothing pins it.
		default:
			return result, errors.New("installed cell has unknown signing scope")
		}
	}
	if result.HostSigner == "" || result.RoleSigner == "" {
		return result, errors.New("installed host and role signing identities are required")
	}
	if e.InterRegion != nil {
		wire, err := readInstallationFile(e.InterRegion.AccountJWTFile, 64<<10)
		if err != nil {
			return result, err
		}
		claim, err := jwt.DecodeAccountClaims(strings.TrimSpace(string(wire)))
		if err != nil || !operator.DidSign(claim) || claim.Subject == system.Subject || claim.Subject == cell.Subject {
			return result, errors.New("installed interregion account is not bound to operator")
		}
		result.InterRegionAccount = claim.Subject
	}
	return result, nil
}

func readInstallationFile(path string, limit int64) ([]byte, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return nil, ErrStoreIdentity
	}
	dir, err := openInstallationDirectory(filepath.Dir(path), false)
	if err != nil {
		return nil, err
	}
	defer unix.Close(dir)
	return readInstallationFileAt(dir, filepath.Base(path), limit)
}

func openInstallationDirectory(path string, create bool) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path || create && path == "/" {
		return -1, ErrStoreIdentity
	}
	dir, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	for component := range strings.SplitSeq(strings.TrimPrefix(path, "/"), "/") {
		if component == "" {
			continue
		}
		next, err := unix.Openat(dir, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		if create && errors.Is(err, unix.ENOENT) {
			if err = unix.Mkdirat(dir, component, 0o700); err == nil || errors.Is(err, unix.EEXIST) {
				err = unix.Fsync(dir)
			}
			if err == nil {
				next, err = unix.Openat(dir, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
			}
		}
		unix.Close(dir)
		if err != nil {
			return -1, err
		}
		dir = next
	}
	return dir, nil
}

func readInstallationFileAt(dir int, name string, limit int64) ([]byte, error) {
	file, wire, err := openInstallationFileAt(dir, name, limit)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	return wire, nil
}

func openInstallationFileAt(dir int, name string, limit int64) (*os.File, []byte, error) {
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_NOFOLLOW|unix.O_NONBLOCK|unix.O_CLOEXEC, 0)
	if err != nil {
		return nil, nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	wire, err := readInstallationDescriptor(dir, file, limit)
	if err != nil {
		file.Close()
		return nil, nil, err
	}
	return file, wire, nil
}

func readInstallationDescriptor(dir int, file *os.File, limit int64) ([]byte, error) {
	var stat unix.Stat_t
	if err := unix.Fstat(int(file.Fd()), &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Nlink != 1 ||
		stat.Mode&0o7777 != 0o600 || stat.Size <= 0 || stat.Size > limit {
		return nil, ErrStoreIdentity
	}
	if _, err := file.Seek(0, io.SeekStart); err != nil {
		return nil, err
	}
	wire, err := io.ReadAll(io.LimitReader(file, limit+1))
	if err != nil {
		return nil, err
	}
	var current unix.Stat_t
	if err := unix.Fstatat(dir, file.Name(), &current, unix.AT_SYMLINK_NOFOLLOW); err != nil ||
		current.Dev != stat.Dev || current.Ino != stat.Ino || current.Mode != stat.Mode || current.Nlink != 1 ||
		int64(len(wire)) != stat.Size || current.Size != stat.Size {
		return nil, ErrStoreIdentity
	}
	return wire, nil
}

func checkUnpinnedInstallationStore(dir int) error {
	fd, err := unix.Openat(dir, "jetstream", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	file := os.NewFile(uintptr(fd), "jetstream")
	defer file.Close()
	entries, err := file.ReadDir(1)
	if err != nil && !errors.Is(err, io.EOF) {
		return err
	}
	if len(entries) != 0 {
		return ErrStoreIdentity
	}
	return nil
}

func publishInstallationPin(dir int, name string, wire []byte) (*os.File, error) {
	return publishInstallationPinOwned(dir, name, wire, uint32(os.Geteuid()), uint32(os.Getegid()))
}

func publishInstallationPinOwned(dir int, name string, wire []byte, uid, gid uint32) (*os.File, error) {
	temporary := "." + name + "." + rand.Text()
	fd, err := unix.Openat(dir, temporary, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0o600)
	if err != nil {
		return nil, err
	}
	defer unix.Unlinkat(dir, temporary, 0)
	file := os.NewFile(uintptr(fd), temporary)
	defer file.Close()
	if err := file.Chown(int(uid), int(gid)); err != nil {
		return nil, err
	}
	if n, err := file.Write(wire); err != nil || n != len(wire) {
		return nil, errors.Join(err, io.ErrShortWrite)
	}
	if err := file.Sync(); err != nil {
		return nil, err
	}
	if err := file.Close(); err != nil {
		return nil, err
	}
	// Publish complete bytes without replacing any concurrent owner's pin.
	if err := unix.Renameat2(dir, temporary, dir, name, unix.RENAME_NOREPLACE); err != nil && !errors.Is(err, unix.EEXIST) {
		return nil, err
	}
	if err := unix.Fsync(dir); err != nil {
		return nil, err
	}
	pinned, recorded, err := openInstallationFileAt(dir, name, 4096)
	if err != nil {
		return nil, err
	}
	if !bytes.Equal(recorded, wire) {
		pinned.Close()
		return nil, ErrStoreIdentity
	}
	return pinned, nil
}

func ObserveIdentityRekeyInstallation(cfg Config, observedRaftNodeID string) (InstallationIdentity, error) {
	if cfg.Embedded == nil || !validNodeID(observedRaftNodeID) {
		return InstallationIdentity{}, ErrStoreIdentity
	}
	if err := cfg.validate(); err != nil {
		return InstallationIdentity{}, err
	}
	dir, err := openInstallationDirectory(cfg.Embedded.StoreDir, false)
	if err != nil {
		return InstallationIdentity{}, err
	}
	defer unix.Close(dir)
	return observeIdentityRekeyInstallation(cfg, dir, observedRaftNodeID)
}

func observeIdentityRekeyInstallation(cfg Config, dir int, observedRaftNodeID string) (InstallationIdentity, error) {
	wire, err := readInstallationFileAt(dir, nodeIdentityFile, 4096)
	if errors.Is(err, os.ErrNotExist) {
		wire, err = json.Marshal(nodeIdentity{Version: 1, Cell: cfg.Cell, Instance: cfg.Instance, NodeID: observedRaftNodeID})
	}
	if err != nil {
		return InstallationIdentity{}, err
	}
	identity, err := observeInstallationIdentity(cfg, dir, wire)
	if err != nil {
		return InstallationIdentity{}, err
	}
	if identity.RaftNodeID != observedRaftNodeID {
		return InstallationIdentity{}, ErrStoreIdentity
	}
	return identity, nil
}

func pinIdentityRekeyInstallation(cfg Config, expected InstallationIdentity, serviceUID, serviceGID uint32) error {
	if cfg.Embedded == nil || serviceUID == 0 || serviceGID == 0 || !validNodeID(expected.RaftNodeID) {
		return ErrStoreIdentity
	}
	if err := cfg.validate(); err != nil {
		return err
	}
	dir, err := openInstallationDirectory(cfg.Embedded.StoreDir, false)
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	observed, err := observeIdentityRekeyInstallation(cfg, dir, expected.RaftNodeID)
	if err != nil {
		return err
	}
	if observed != expected {
		return ErrStoreIdentity
	}
	file, recorded, err := openInstallationFileAt(dir, nodeIdentityFile, 4096)
	if err == nil {
		defer file.Close()
		var stat unix.Stat_t
		if err := unix.Fstat(int(file.Fd()), &stat); err != nil || stat.Uid != serviceUID || stat.Gid != serviceGID {
			return ErrStoreIdentity
		}
		if installationDigest(recorded) != expected.NodeIdentitySHA256 {
			return ErrStoreIdentity
		}
		return unix.Fsync(dir)
	}
	if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	wire, err := json.Marshal(nodeIdentity{Version: 1, Cell: cfg.Cell, Instance: cfg.Instance, NodeID: expected.RaftNodeID})
	if err != nil {
		return err
	}
	if installationDigest(wire) != expected.NodeIdentitySHA256 {
		return ErrStoreIdentity
	}
	file, err = publishInstallationPinOwned(dir, nodeIdentityFile, wire, serviceUID, serviceGID)
	if err != nil {
		return err
	}
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(int(file.Fd()), &stat); err != nil || stat.Uid != serviceUID || stat.Gid != serviceGID {
		return ErrStoreIdentity
	}
	current, err := readInstallationDescriptor(dir, file, 4096)
	if err != nil {
		return err
	}
	if !bytes.Equal(current, wire) {
		return ErrStoreIdentity
	}
	actual, err := observeInstalledIdentity(cfg, dir)
	if err != nil {
		return err
	}
	if actual != expected {
		return ErrStoreIdentity
	}
	return unix.Fsync(dir)
}

func pinNodeIdentity(dir, cell, instance, nodeID string) error {
	return pinNodeIdentityWithSync(dir, cell, instance, nodeID, syncIdentityDirectory)
}

func pinNodeIdentityWithSync(dir, cell, instance, nodeID string, syncDirectory func(string) error) error {
	if cell == "" || instance == "" || !validNodeID(nodeID) {
		return fmt.Errorf("%w: invalid Raft store identity", ErrStoreIdentity)
	}
	want := nodeIdentity{Version: 1, Cell: cell, Instance: instance, NodeID: nodeID}
	path := filepath.Join(dir, nodeIdentityFile)
	check := func() error {
		info, err := os.Lstat(path)
		if err != nil {
			return err
		}
		if !info.Mode().IsRegular() || info.Mode().Perm() != 0o600 || info.Size() > 1024 {
			return fmt.Errorf("%w: invalid node identity file", ErrStoreIdentity)
		}
		wire, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		var recorded nodeIdentity
		if err := protocol.DecodeStrict(wire, &recorded, 1024); err != nil || recorded != want {
			return fmt.Errorf("%w: node identity differs from this cell/controller and Raft ID", ErrStoreIdentity)
		}
		return nil
	}
	if err := check(); !errors.Is(err, fs.ErrNotExist) {
		if err != nil {
			return err
		}
		return syncDirectory(dir)
	}
	wire, err := json.Marshal(want)
	if err != nil {
		return err
	}
	temp, err := os.CreateTemp(dir, "node-identity.*")
	if err != nil {
		return err
	}
	defer os.Remove(temp.Name())
	defer temp.Close()
	if _, err := temp.Write(wire); err != nil {
		return err
	}
	if err := temp.Sync(); err != nil {
		return err
	}
	if err := temp.Close(); err != nil {
		return err
	}
	// Link publishes a complete record without replacing another starter's pin.
	if err := os.Link(temp.Name(), path); err != nil && !errors.Is(err, fs.ErrExist) {
		return err
	}
	if err := syncDirectory(dir); err != nil {
		return err
	}
	return check()
}

func syncIdentityDirectory(dir string) error {
	directory, err := os.Open(dir)
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

func validNodeID(id string) bool {
	if len(id) != 8 {
		return false
	}
	for _, ch := range id {
		if !(ch >= '0' && ch <= '9' || ch >= 'A' && ch <= 'Z' || ch >= 'a' && ch <= 'z') {
			return false
		}
	}
	return true
}

func pinStoreIdentity(dir, name, legacy string) error {
	path := filepath.Join(dir, storeIdentityFile)
	recorded, err := os.ReadFile(path)
	if err == nil {
		if owner := strings.TrimSuffix(string(recorded), "\n"); owner != name {
			return fmt.Errorf("%w: store %s belongs to %q, not %q; the cell must be rebuilt (TS-470)", ErrStoreIdentity, dir, owner, name)
		}
		return nil
	}
	if !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("read NATS store identity: %w", err)
	}
	if name != legacy {
		entries, err := os.ReadDir(filepath.Join(dir, "jetstream"))
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("read NATS store: %w", err)
		}
		if len(entries) > 0 {
			return fmt.Errorf("%w: store %s holds JetStream state of %q, not %q; the cell must be rebuilt (TS-470)", ErrStoreIdentity, dir, legacy, name)
		}
	}
	temp, err := os.CreateTemp(dir, storeIdentityFile+".*")
	if err != nil {
		return fmt.Errorf("record NATS store identity: %w", err)
	}
	defer os.Remove(temp.Name())
	if _, err := temp.WriteString(name + "\n"); err != nil {
		temp.Close()
		return fmt.Errorf("record NATS store identity: %w", err)
	}
	if err := temp.Close(); err != nil {
		return fmt.Errorf("record NATS store identity: %w", err)
	}
	return os.Rename(temp.Name(), path)
}

func (keys testRegionKeys) childKey(t *testing.T, child string) nkeys.KeyPair {
	t.Helper()
	if key, ok := keys.children[child]; ok {
		return key
	}
	key, err := nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	keys.children[child] = key
	return key
}

func newTestRegionKeys(t *testing.T) testRegionKeys {
	t.Helper()
	var keys testRegionKeys
	var err error
	if keys.operator, err = nkeys.CreateOperator(); err != nil {
		t.Fatal(err)
	}
	for _, account := range []*nkeys.KeyPair{&keys.system, &keys.cell, &keys.interregion} {
		if *account, err = nkeys.CreateAccount(); err != nil {
			t.Fatal(err)
		}
	}
	keys.operatorID, _ = keys.operator.PublicKey()
	keys.systemID, _ = keys.system.PublicKey()
	keys.cellID, _ = keys.cell.PublicKey()
	keys.interregionID, _ = keys.interregion.PublicKey()
	keys.children = map[string]nkeys.KeyPair{}
	keys.t = t
	return keys
}

func (keys testRegionKeys) claims(contract InterRegionContract, links int) (*jwt.AccountClaims, *jwt.AccountClaims, *jwt.AccountClaims) {
	childKeys := map[string]string{}
	for child := range contract.Subtrees {
		childKeys[child], _ = keys.childKey(keys.t, child).PublicKey()
	}
	system := jwt.NewAccountClaims(keys.systemID)
	system.Limits.LeafNodeConn = 0
	cell := jwt.NewAccountClaims(keys.cellID)
	cell.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: 64 << 20, DiskStorage: 256 << 20, Streams: 20, Consumer: 20}
	contract.ApplyCell(cell, keys.interregionID)
	interregion := jwt.NewAccountClaims(keys.interregionID)
	contract.ApplyInterRegion(interregion, keys.cellID, links, childKeys)
	return system, cell, interregion
}

func newTestRegion(t *testing.T, root, cell string, topology LeafTopology) *testRegion {
	t.Helper()
	if err := os.MkdirAll(root, 0o700); err != nil {
		t.Fatal(err)
	}
	keys := newTestRegionKeys(t)
	peers := topology.Peers(cell)
	subtrees := topology.Subtrees(cell)
	contract := InterRegionContract{Cell: cell, Peers: peers, GlobalHome: topology.Hub, Subtrees: subtrees}
	links := topology.Links(cell)
	system, cellClaim, interregion := keys.claims(contract, links)
	operator := jwt.NewOperatorClaims(keys.operatorID)
	operator.SystemAccount = keys.systemID
	write := func(name, data string) string {
		t.Helper()
		path := filepath.Join(root, name)
		if err := os.WriteFile(path, []byte(data), 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}
	encode := func(name string, claim interface {
		Encode(nkeys.KeyPair) (string, error)
	},
	) string {
		t.Helper()
		raw, err := claim.Encode(keys.operator)
		if err != nil {
			t.Fatal(err)
		}
		return write(name, raw)
	}
	systemUser, _ := nkeys.CreateUser()
	systemUserID, _ := systemUser.PublicKey()
	tlsFiles := testBridgeTLS(t, filepath.Join(root, "tls"))
	cfg := Config{
		Cell: cell, Instance: "broker-a", Replicas: 1, TLS: tlsFiles,
		CredentialsFile: testJWTUserCredentials(t, root, "controller.creds", keys.cell, keys.cellID, nil, nil),
		Embedded: &Embedded{
			Host: "127.0.0.1", Port: freeClientPort(t), StoreDir: filepath.Join(root, "store"),
			TLS: tlsFiles, RouteTLS: tlsFiles,
			OperatorJWTFile: encode("operator.jwt", operator),
			SystemJWTFile:   encode("system.jwt", system),
			CellJWTFile:     encode("cell.jwt", cellClaim),
			SystemCredentialsFile: testJWTUserCredentialsWithKey(t, root, "system.creds", keys.system, keys.systemID, systemUser,
				[]string{"$SYS.REQ.ACCOUNT." + keys.cellID + ".CLAIMS.UPDATE"}, []string{inboxPrefix(cell, systemUserID) + ".>"}),
			TicketPublicKeyFile: write("ticket.pub", "unused"),
			BrokerIDs:           []string{"broker-a"},
			InterRegion: &InterRegion{
				Peers: peers, AccountJWTFile: encode("interregion.jwt", interregion),
				GlobalHome: topology.Hub, Subtrees: subtrees,
			},
		},
	}
	return &testRegion{testRegionKeys: keys, cfg: cfg}
}

func (cfg Config) validate() error {
	if len(cfg.OperatorForward) != 0 {
		if _, _, err := operatorForwarding(cfg); err != nil {
			return err
		}
	}
	if !cellName.MatchString(cfg.Cell) || !cellName.MatchString(cfg.Instance) {
		return errors.New("cell and instance must be lowercase NATS tokens")
	}
	// Every protocol subject builder refuses the reserved scope as a cell
	// and returns "", which would surface far from here as empty grants.
	if cfg.Cell == protocol.GlobalScope {
		return errors.New("cell name is reserved for the global scope")
	}
	if cfg.Replicas != 1 && cfg.Replicas != 3 && cfg.Replicas != 5 {
		return errors.New("regional replicas must be 1, 3, or 5")
	}
	if cfg.ClientRole != "" && cfg.ClientRole != "controller" && cfg.ClientRole != "operator" && cfg.ClientRole != "host" {
		return errors.New("invalid regional NATS client role")
	}
	if cfg.Embedded == nil && cfg.URL == "" {
		return errors.New("regional NATS URL or embedded server is required")
	}
	if cfg.NKeySeedFile != "" && cfg.CredentialsFile != "" {
		return errors.New("choose one regional NKey seed or JWT credentials file")
	}
	if !cfg.TLS.complete() || cfg.CredentialsFile == "" || cfg.NKeySeedFile != "" {
		return errors.New("regional NATS requires client TLS and JWT credentials")
	}
	if cfg.Embedded != nil && (!cfg.Embedded.TLS.complete() || !cfg.Embedded.RouteTLS.complete() ||
		cfg.Embedded.OperatorJWTFile == "" || cfg.Embedded.SystemJWTFile == "" ||
		cfg.Embedded.CellJWTFile == "" || cfg.Embedded.SystemCredentialsFile == "" ||
		cfg.Embedded.TicketPublicKeyFile == "" || len(cfg.Embedded.BrokerIDs) != cfg.Replicas || len(cfg.Embedded.Users) != 0) {
		return errors.New("production embedded NATS requires operator/system/cell JWTs, system credentials, and client/route TLS")
	}
	if cfg.Embedded != nil {
		e := cfg.Embedded
		if e.InterRegion != nil && e.Link != nil {
			return errors.New("a region links to peers by interregion or by link, not both")
		}
		if err := e.InterRegion.validate(cfg); err != nil {
			return err
		}
		if e.Link != nil {
			if err := e.Link.validate(cfg); err != nil {
				return err
			}
		}
		seen := make(map[string]struct{}, len(e.BrokerIDs))
		for _, id := range e.BrokerIDs {
			if !cellName.MatchString(id) {
				return errors.New("production broker ID is invalid")
			}
			if _, exists := seen[id]; exists {
				return errors.New("production broker IDs must be unique")
			}
			seen[id] = struct{}{}
		}
		if _, own := seen[cfg.Instance]; !own {
			return errors.New("production broker ID list excludes this instance")
		}
		if e.StoreDir == "" || e.Host == "" || e.Port == 0 {
			return errors.New("embedded NATS requires store_dir, host, and port")
		}
		if e.StoreMaxBytes < 0 {
			return errors.New("embedded NATS store_max_bytes must be positive when set")
		}
		if cfg.Replicas > 1 && (e.RouteHost == "" || e.RoutePort == 0 || len(e.Routes) == 0) {
			return errors.New("clustered NATS requires route_host, route_port and at least one seed route")
		}
		if cfg.Replicas > 1 && (e.RouteUser == "" || e.RoutePasswordFile == "") {
			return errors.New("production NATS routes require a route user and password file")
		}
	}
	return nil
}

func (ir *InterRegion) GlobalControlHome(cell string) (string, error) {
	home := cell
	if ir != nil {
		home = ir.GlobalHome
		if ir.Topology != nil {
			if err := ir.matchTopology(cell, *ir.Topology); err != nil {
				return "", err
			}
			home = ir.Topology.Hub
		}
		if home != cell && !slices.Contains(ir.Peers, home) {
			return "", errors.New("interregion global home must be this region or a roster peer")
		}
	}
	if token, err := protocol.RegionToken(home); err != nil || token != home || token == protocol.GlobalScope {
		return "", errors.New("global control home must be a lowercase regional cell")
	}
	return home, nil
}

func (ir *InterRegion) validate(cfg Config) error {
	if ir == nil {
		return nil
	}
	if ir.AccountJWTFile == "" {
		return errors.New("interregion account JWT is required")
	}
	if len(ir.Peers) > 63 {
		return errors.New("interregion peers must list at most 63 regions")
	}
	seen := map[string]bool{cfg.Cell: true}
	for _, peer := range ir.Peers {
		if !cellName.MatchString(peer) || peer == protocol.GlobalScope || seen[peer] {
			return fmt.Errorf("interregion peer %q is invalid or repeated", peer)
		}
		seen[peer] = true
	}
	home, err := ir.GlobalControlHome(cfg.Cell)
	if err != nil {
		return err
	}
	// The leaf tree is rooted at the global home. LeafPermissions relies on
	// it: an accepted leaf never speaks for the home, so a home that dialed
	// a parent would have its health, queries and mirror feeds refused there.
	if home == cfg.Cell && len(ir.Remotes) != 0 {
		return errors.New("the interregion global home is the leaf tree root and must not dial remotes")
	}
	if len(ir.Peers) != 0 && ir.Listen == nil && len(ir.Remotes) == 0 {
		return errors.New("interregion needs a leaf listener or at least one remote")
	}
	// The home is the tree root and never dials out, so a non-home region
	// reaches it, and its mirror feed, only through a parent remote.
	if home != cfg.Cell && len(ir.Remotes) == 0 {
		return errors.New("a non-home region must dial a remote to reach the interregion global home")
	}
	if ir.Listen != nil && (ir.Listen.Host != "0.0.0.0" || ir.Listen.Port <= 0 || !ir.Listen.TLS.complete()) {
		return errors.New("interregion leaf listener requires host 0.0.0.0, port, and mutual TLS")
	}
	if (ir.Listen != nil) != (len(ir.Subtrees) != 0) {
		return errors.New("interregion leaf listener and child subtrees must be configured together")
	}
	reached := map[string]bool{}
	for child, subtree := range ir.Subtrees {
		if !slices.Contains(subtree, child) {
			return fmt.Errorf("interregion child %q must be in its own subtree", child)
		}
		for _, region := range subtree {
			if !slices.Contains(ir.Peers, region) || region == home || reached[region] {
				return fmt.Errorf("interregion subtree of %q names %q, which is not a unique non-home peer", child, region)
			}
			reached[region] = true
		}
	}
	// The tree root (no parent remote) reaches every peer through its child
	// subtrees; a peer in none would be in the contract yet unreachable,
	// and every request to it would hang without a responder. A region
	// with a parent reaches the rest of the tree through it.
	if len(ir.Remotes) == 0 {
		for _, peer := range ir.Peers {
			if !reached[peer] {
				return fmt.Errorf("interregion roster peer %q is in no child subtree and this region dials no parent", peer)
			}
		}
	}
	remotes := map[string]bool{}
	for _, remote := range ir.Remotes {
		if !slices.Contains(ir.Peers, remote.Peer) || remotes[remote.Peer] || reached[remote.Peer] {
			return fmt.Errorf("interregion remote %q is not a unique roster peer outside the child subtrees", remote.Peer)
		}
		remotes[remote.Peer] = true
		if len(remote.URLs) == 0 || remote.CredentialsFile == "" || !remote.TLS.complete() ||
			!nkeys.IsValidPublicAccountKey(remote.PeerAccount) {
			return fmt.Errorf("interregion remote %q requires URLs, credentials, peer account, and mutual TLS", remote.Peer)
		}
		if len(remote.ServerName) > 253 || !leafServerName.MatchString(remote.ServerName) || net.ParseIP(remote.ServerName) != nil {
			return fmt.Errorf("interregion remote %q server_name must be a DNS name", remote.Peer)
		}
		for _, raw := range remote.URLs {
			parsed, err := url.Parse(raw)
			if err != nil || parsed.Scheme != "nats-leaf" || parsed.Host == "" || parsed.User != nil ||
				parsed.Path != "" || parsed.RawQuery != "" {
				return fmt.Errorf("interregion remote %q URL must be nats-leaf://host:port", remote.Peer)
			}
		}
	}
	return nil
}

func (ir *InterRegion) matchTopology(cell string, topology LeafTopology) error {
	if err := topology.Validate(); err != nil {
		return fmt.Errorf("interregion topology: %w", err)
	}
	if !slices.Contains(topology.Regions(), cell) {
		return fmt.Errorf("interregion topology does not contain this region %q", cell)
	}
	if ir.GlobalHome != "" && ir.GlobalHome != topology.Hub {
		return fmt.Errorf("interregion global home %q is not the topology hub %q", ir.GlobalHome, topology.Hub)
	}
	if !slices.Equal(slices.Sorted(slices.Values(ir.Peers)), topology.Peers(cell)) {
		return errors.New("interregion peers differ from the other regions of the topology")
	}
	expected := topology.Subtrees(cell)
	if len(expected) != len(ir.Subtrees) {
		return errors.New("interregion child subtrees differ from the topology")
	}
	for child, subtree := range expected {
		if !slices.Equal(slices.Sorted(slices.Values(ir.Subtrees[child])), subtree) {
			return fmt.Errorf("interregion subtree of child %q differs from the topology", child)
		}
	}
	parent, dials := topology.Parent(cell)
	if !dials && len(ir.Remotes) != 0 || dials && (len(ir.Remotes) != 1 || ir.Remotes[0].Peer != parent) {
		return errors.New("interregion remotes must be exactly this region's topology parent")
	}
	return nil
}

func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

